/* Teacher monitoring reads the same Firebase evidence students submit.
 * Feedback is separate from the protected rubric/official grade records. */
const G11Monitor=(()=>{
 let feedbackDrafts={},progress={},accounts={},images={},selected='',filter='all',started=false,progressError='';
 const esc=s=>escHtml(String(s??''));
 const pairs=[['intro',['tn-webcam-image-classification','tn-card-sorting-activity']],['train',['tn-machine-learning-image-classification','tn-image-upload-classifier']],['live',['tn-webcam-live-classifier','tn-webcam-live-classifier-coding-project','tn-adjustable-accuracy-webcam-classifier']],['music',['tn-responsive-instrument','tn-music-generator']],['chess',['tn-ai-chess-player']],['assistant',['tn-ai-digital-assistant']],['rescue',['tn-ai-animal-rescue']],['navigation',['tn-ai-navigation-algorithm']],['auto',['tn-ai-auto-navigation']],['finish',['tn-ai-find-the-finish-line']]];
 const map=Object.fromEntries(pairs);
 function sources(id){if(id.startsWith('g11AiCompletion_'))return (map[id.replace('g11AiCompletion_','')]||[]).map(n=>['projects',n]);return [["lessons",{g11AiFormative1:1,g11AiFormative2:4,g11AiFormative3:13,g11AiSummative:14}[id]]].filter(([,key])=>key);}
 function version(studentId,id){return sources(id).map(([kind,key])=>kind+'/'+key+':'+(progress[studentId]?.student?.[kind]?.[key]?.revision||0)).join('|');}
 function pendingCount(id){const row=progress[id]||{},grade=allSiswa.find(s=>s.id===id)?.digitalCitizenshipAssessment?.q2;return ['1','4','13'].filter((k,i)=>{const v=row.student?.lessons?.[k],r=row.teacher?.reviews?.['l_'+k],assessment='g11AiFormative'+(i+1),graded=grade?.reviewed?.[assessment]===true&&grade.evidenceVersions?.[assessment]===version(id,assessment);return v?.done&&(!graded||r?.status==='needs_revision');}).length;}
 function checkStale(){if(typeof dcTeacherState==='undefined'||dcTeacherState.grade!==11||dcTeacherState.quarter!==2)return;const draft=dcTeacherState.draft;let changed=false;for(const a of G11_AI_WEIGHTED_ASSESSMENTS){const known=draft.evidenceVersions?.[a.id];if(draft.reviewed?.[a.id]===true&&known!==undefined&&known!==version(dcTeacherState.studentId,a.id)){draft.reviewed[a.id]=false;changed=true;}}if(changed){dcTeacherState.dirty=true;renderDcAssessmentPanel();showAlert('Siswa mengirim versi bukti baru. Periksa kembali komponen yang berubah; nilai resmi terakhir tetap tersedia.','warning');}}
 function render(){const root=document.getElementById('g11MonitorList');if(!root)return;const classFilter=document.getElementById('g11MonitorClass')?.value||'',query=(document.getElementById('g11MonitorSearch')?.value||'').toLowerCase();const students=allSiswa.filter(s=>getTeacherStudentGrade(s)===11&&(!classFilter||s.kelas===classFilter)&&String(s.nama).toLowerCase().includes(query)&&(filter!=='pending'||pendingCount(s.id)>0));const classes=[...new Set(allSiswa.filter(s=>getTeacherStudentGrade(s)===11).map(s=>s.kelas))];const choice=document.getElementById('g11MonitorClass');if(choice&&choice.options.length<=1){choice.innerHTML='<option value="">Semua kelas 11</option>'+classes.map(c=>'<option>'+esc(c)+'</option>').join('');}
 root.innerHTML=students.map(s=>{const row=progress[s.id]?.student||{},ready=['1','4','13'].filter(k=>row.lessons?.[k]?.done).length,count=pendingCount(s.id);return '<article class="g11-monitor-row"><div><b>'+esc(s.nama)+'</b><small>'+esc(s.kelas)+' · '+ready+'/3 formatif diajukan · '+count+' menunggu pemeriksaan</small></div><div><button type="button" data-student="'+esc(s.id)+'" class="dc-save-button g11-monitor-open">Lihat bukti & nilai</button>'+(!accounts[s.id]?.uid?'<button type="button" data-student="'+esc(s.id)+'" class="dc-save-button g11-monitor-activate">Aktifkan akun cloud</button>':'')+'</div></article>';}).join('')||'<p class="g11-monitor-empty">Belum ada siswa yang sesuai filter.</p>';root.querySelectorAll('.g11-monitor-open').forEach(b=>b.addEventListener('click',()=>open(b.dataset.student)));root.querySelectorAll('.g11-monitor-activate').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{await G11CloudIdentity.activate(allSiswa.find(s=>s.id===b.dataset.student));showAlert('Akun cloud aktif. Siswa dapat masuk dengan password CS.Report yang sama.','success');}catch(e){showAlert(e.message,'danger');}finally{b.disabled=false;}}));renderEvidence();}
 function open(id){if(dcTeacherState.saving)return;if(dcTeacherState.dirty&&!window.confirm('Ada rubrik yang belum disimpan. Tetap membuka siswa ini?'))return;dcTeacherState.dirty=false;changeDcAssessmentGrade(11);setQuarter(2);selected=id;dcTeacherState.studentId=id;document.getElementById('dcAssessmentStudent').value=id;dcTeacherState.selectedAssessmentId='g11AiFormative1';loadDcAssessmentDraft();renderEvidence();document.getElementById('dcAssessmentPanel').scrollIntoView({behavior:'smooth'});}
 function proofLinks(value){return [...new Set(String(value||'').match(/https?:\/\/[^\s<>"']+/g)||[])].slice(0,5).map(u=>'<a class="dc-save-button" href="'+esc(u)+'" target="_blank" rel="noopener noreferrer">Buka tautan bukti ↗</a>').join(' ');}
 /* Screenshots live in learningEvidenceImages/{student}/{imageId} and load only
  * when their evidence is opened; older records may still carry inline data. */
 const validImage=data=>typeof data==='string'&&data.length<=320000&&/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(data);
 function proofScreenshots(value,studentId){const shots=(value&&typeof value==='object'?Object.values(value):[]).slice(0,2).filter(item=>item&&(validImage(item.data)||/^[a-f0-9]{32}$/.test(item.imageId||'')));return shots.length?'<div class="g11-proof-grid">'+shots.map((shot,index)=>{const src=validImage(shot.data)?shot.data:images[studentId+'/'+shot.imageId]||'';return '<button type="button" class="g11-proof-open" aria-label="Perbesar screenshot bukti '+(index+1)+'"><img '+(src?'src="'+esc(src)+'"':'data-g11-image="'+esc(shot.imageId)+'"')+' alt="Screenshot bukti '+(index+1)+'"><span>'+esc(shot.name||'Screenshot '+(index+1))+' · Perbesar</span></button>';}).join('')+'</div>':'<p class="g11-evidence-missing">Belum ada screenshot bukti.</p>';}
 function loadImages(target,studentId){target.querySelectorAll('img[data-g11-image]').forEach(img=>{const key=studentId+'/'+img.dataset.g11Image;db.ref('learningEvidenceImages').child(studentId).child(img.dataset.g11Image).once('value').then(snap=>{const data=snap.val()?.data;if(!validImage(data))throw Error('missing');images[key]=data;img.src=data;img.removeAttribute('data-g11-image');}).catch(()=>{img.alt='Screenshot belum dapat dimuat. Muat ulang dashboard.';});});}
 function evidenceHTML(studentId,assessmentId){
  const row=progress[studentId]||{},related=sources(assessmentId);
  return related.map(([kind,key])=>{
   const data=row.student?.[kind]?.[key],reviewKey=(kind==='projects'?'p_':'l_')+key,r=feedbackDrafts[studentId+'/'+reviewKey]||row.teacher?.reviews?.[reviewKey],label=kind==='projects'?key.replace(/^tn-/,'').replaceAll('-',' '):'Bukti '+assessmentId.replace('g11AiFormative','F'),isReady=kind==='projects'?data?.ready:data?.done;
   return '<article class="g11-evidence"><h4>'+esc(label)+'</h4><small>'+(!data?'Belum ada jawaban tersimpan':isReady?'Diajukan · revisi '+(data.revision||0):'Draft tersimpan · belum diajukan · revisi '+(data.revision||0))+'</small><p class="g11-evidence-caption">Jawaban asli siswa di bawah ini hanya dapat dibaca. Gunakan feedback untuk meminta perbaikan.</p><h5>Screenshot bukti</h5>'+proofScreenshots(data?.screenshots,studentId)+'<label for="g11-answer-'+reviewKey+'">1. Perubahan & prediksimu · jawaban siswa</label><textarea readonly rows="4" id="g11-answer-'+reviewKey+'" class="g11-student-answer" placeholder="Belum diisi siswa.">'+esc(data?.evidence||'')+'</textarea>'+proofLinks(data?.evidence)+'<label for="g11-result-'+reviewKey+'">2. Hasil uji & satu keterbatasan · jawaban siswa</label><textarea readonly rows="5" id="g11-result-'+reviewKey+'" class="g11-student-answer" placeholder="Belum diisi siswa. Hasil uji dan satu keterbatasan ditulis bersama di kolom ini.">'+esc(data?.reflection||'')+'</textarea><label>Feedback guru<textarea maxlength="2000" id="g11-feedback-'+reviewKey+'">'+esc(r?.message||'')+'</textarea></label><label>Status pemeriksaan<select id="g11-status-'+reviewKey+'"><option value="seen">Sudah dilihat</option><option value="needs_revision" '+(r?.status==='needs_revision'?'selected':'')+'>Perlu revisi</option><option value="accepted" '+(r?.status==='accepted'?'selected':'')+'>Diterima</option></select></label><button type="button" '+(!data?'disabled ':'')+'data-revision="'+(data?.revision||0)+'" data-key="'+reviewKey+'" data-kind="'+kind+'" data-source="'+key+'" class="dc-save-button g11-feedback-save">Kirim feedback</button></article>';
  }).join('');
 }
 function evidenceTabsHTML(id){return '<div class="g11-evidence-tabs" aria-label="Pilih bukti formatif">'+[1,4,13].map((key,i)=>{const assessment='g11AiFormative'+(i+1),r=progress[id]?.student?.lessons?.[key],hasText=Boolean(r?.evidence?.trim()||r?.reflection?.trim()),status=r?.done?'Diajukan':hasText||r?.screenshots?.length?'Draft tersimpan':'Belum diisi';return '<button type="button" data-assessment="'+assessment+'" class="g11-evidence-switch" aria-pressed="'+(dcTeacherState.selectedAssessmentId===assessment)+'"><b>F'+(i+1)+'</b><span>'+status+'</span></button>';}).join('')+'</div>';}
 function bindScreenshotViewer(target){target.querySelectorAll('.g11-proof-open').forEach(button=>button.addEventListener('click',()=>{const dialog=document.createElement('dialog');dialog.className='g11-proof-dialog';dialog.innerHTML='<button type="button" class="dc-save-button">Tutup screenshot</button><img alt="Screenshot bukti siswa ukuran penuh">';dialog.querySelector('img').src=button.querySelector('img').src;dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();});dialog.addEventListener('close',()=>dialog.remove(),{once:true});document.body.append(dialog);dialog.showModal();}));}
 function renderEvidence(){
  const target=document.getElementById('g11EvidencePanel');if(!target||dcTeacherState.grade!==11||dcTeacherState.quarter!==2)return;const id=dcTeacherState.studentId;
  if(target.contains(document.activeElement))return;
  target.innerHTML='<h3>Bukti formatif siswa</h3>'+evidenceTabsHTML(id)+(progressError?'<p class="g11-evidence-missing" role="alert">Bukti Firebase belum dapat dimuat. Muat ulang dashboard untuk mencoba lagi.</p>':'')+evidenceHTML(id,dcTeacherState.selectedAssessmentId);
  target.querySelectorAll('.g11-evidence-switch').forEach(button=>button.addEventListener('click',()=>dcSelectAssessment(button.dataset.assessment)));
  bindScreenshotViewer(target);
  loadImages(target,id);
  target.querySelectorAll('.g11-feedback-save').forEach(b=>{const remember=()=>{feedbackDrafts[id+'/'+b.dataset.key]={message:document.getElementById('g11-feedback-'+b.dataset.key).value,status:document.getElementById('g11-status-'+b.dataset.key).value};};document.getElementById('g11-feedback-'+b.dataset.key).addEventListener('input',remember);document.getElementById('g11-status-'+b.dataset.key).addEventListener('change',remember);});
  target.querySelectorAll('.g11-feedback-save').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{const teacher=await G11CloudIdentity.verifyTeacher();await db.ref('learningProgress').child(id).child('grade11Ai/teacher/reviews').child(b.dataset.key).set({message:document.getElementById('g11-feedback-'+b.dataset.key).value,status:document.getElementById('g11-status-'+b.dataset.key).value,sourceRevision:Number(b.dataset.revision)||0,updatedAt:G11CloudIdentity.stamp(),updatedBy:teacher.uid});delete feedbackDrafts[id+'/'+b.dataset.key];showAlert('Feedback terkirim ke siswa. Nilai diisi dan disimpan melalui rubrik.','success');}catch(e){showAlert('Feedback belum terkirim: '+e.message,'danger');}finally{b.disabled=false;}}));
 }
 function mount(){const panel=document.getElementById('g11MonitorPanel');if(!panel)return;document.getElementById('g11MonitorSearch').addEventListener('input',render);document.getElementById('g11MonitorClass').addEventListener('change',render);document.getElementById('g11MonitorFilter').addEventListener('change',e=>{filter=e.target.value;render();});}
 function start(){if(started)return;started=true;mount();db.ref('grade11AiAccounts').on('value',snap=>{accounts=snap.val()||{};render();},e=>showAlert('Monitor akun cloud: '+e.message,'danger'));}
 return {open,invalidateStale:checkStale,start,render,renderEvidence,version,sources,onProgressError(error){progressError=String(error?.message||error||'load-error');renderEvidence();},onProgress(value){progressError='';progress={};for(const [id,row]of Object.entries(value||{}))if(row.grade11Ai)progress[id]=row.grade11Ai;checkStale();render();renderEvidence();}};
})();
